        collabStopOverridePrompt: "\u0985\u09A7\u09BF\u09AC\u09C7\u09B6\u09A8 \u09AC\u09A8\u09CD\u09A7 \u0995\u09B0\u09BE \u0986\u09AA\u09A8\u09BE\u09B0 \u09AA\u09C2\u09B0\u09CD\u09AC\u09AC\u09B0\u09CD\u09A4\u09C0, \u09B8\u09CD\u09A5\u09BE\u09A8\u09C0\u09AF\u09BC\u09AD\u09BE\u09AC\u09C7 \u09B8\u099E\u09CD\u099A\u09BF\u09A4 \u0985\u0999\u09CD\u0995\u09A8 \u0993\u09AD\u09BE\u09B0\u09B0\u09BE\u0987\u099F \u0995\u09B0\u09AC\u09C7\u0964 \u0986\u09AA\u09A8\u09BF \u0995\u09BF \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4?\n\n(\u09AF\u09A6\u09BF \u0986\u09AA\u09A8\u09BF \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09CD\u09A5\u09BE\u09A8\u09C0\u09AF\u09BC \u0985\u0999\u09CD\u0995\u09A8 \u09B0\u09BE\u0996\u09A4\u09C7 \u099A\u09BE\u09A8, \u09A4\u09BE\u09B9\u09B2\u09C7 \u09B6\u09C1\u09A7\u09C1 \u09AC\u09CD\u09B0\u09BE\u0989\u099C\u09BE\u09B0 \u099F\u09CD\u09AF\u09BE\u09AC\u099F\u09BF \u09AC\u09A8\u09CD\u09A7 \u0995\u09B0\u09C1\u09A8\u0964)",
        errorAddingToLibrary: "\u09AC\u09B8\u09CD\u09A4\u09C1\u099F\u09BF \u09B8\u0982\u0997\u09CD\u09B0\u09B9\u09C7 \u09AF\u09CB\u0997 \u0995\u09B0\u09BE \u09AF\u09BE\u09AF\u09BC\u09A8\u09BF",
        errorRemovingFromLibrary: "\u09AC\u09B8\u09CD\u09A4\u09C1\u099F\u09BF \u09B8\u0982\u0997\u09CD\u09B0\u09B9 \u09A5\u09C7\u0995\u09C7 \u09AC\u09BF\u09DF\u09CB\u0997 \u0995\u09B0\u09BE \u09AF\u09BE\u09AF\u09BC\u09A8\u09BF",
        confirmAddLibrary: "\u098F\u099F\u09BF \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u0982\u0997\u09CD\u09B0\u09B9\u09C7 {{numShapes}} \u0986\u0995\u09BE\u09B0(\u0997\u09C1\u09B2\u09BF) \u09AF\u09CB\u0997 \u0995\u09B0\u09AC\u09C7\u0964 \u0986\u09AA\u09A8\u09BF \u0995\u09BF \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4?",
