        button_startSession: "\u0A07\u0A1C\u0A32\u0A3E\u0A38 \u0A36\u0A41\u0A30\u0A42 \u0A15\u0A30\u0A4B",
        button_stopSession: "\u0A07\u0A1C\u0A32\u0A3E\u0A38 \u0A30\u0A4B\u0A15\u0A4B",
